INSERT INTO project_note (project_note_id, project_id, content, author_ern, author_given_name, author_family_name, created_at, updated_at) VALUES ('ac6398d0-6c76-4b69-b6d3-8fe40c77c183', 'd0cf7a10-0000-4d0c-8a00-000000000001', 'PL-10 (HAZ-DOC-035): PatientMatchPanel confirm handler must keep the BLOCKED-PL-10 TODO until CSO signs off the wrong-patient hazard. Do not ship to production before sign-off.', 'ern:emis:user:user:9b2c1d4e-5f60-4a71-8c92-d3e4f5061728', 'Dan', 'Watts', '2026-05-29 09:25:00+00', '2026-05-29 09:25:00+00');
INSERT INTO project_note (project_note_id, project_id, content, author_ern, author_given_name, author_family_name, created_at, updated_at) VALUES ('4c173513-54b2-4001-b1d3-f38273d3b086', 'd0cf7a10-0000-4d0c-8a00-000000000001', 'REQ-002 NHSmail production access route with NHS England remains unresolved for go-live. Track before Increment 1 release.', 'ern:emis:user:user:7ae7b859-c480-4644-b3be-d77d628f6e7e', 'Luke', 'Smith', '2026-05-29 11:10:00+00', '2026-05-29 11:10:00+00');
INSERT INTO project_decision (project_decision_id, project_id, title, context, decision, consequences, author_ern, author_given_name, author_family_name, created_at, updated_at) VALUES ('677ef755-8a0b-4373-b428-0b1e49f0fe4a', 'd0cf7a10-0000-4d0c-8a00-000000000001', 'Mandatory human confirmation for all patient matches', 'Automated demographic matching against PDS can return a confident but incorrect match, risking a document being filed to the wrong care record (HAZ-DOC-035).', 'No document may be filed on an automated match alone. A user must confirm the patient via the three-point verification panel before filing completes.', 'Eliminates silent auto-filing to the wrong patient and gives a clear audit point. Adds a confirmation step to every filing action, which is acceptable for clinical safety.', 'ern:emis:user:user:9b2c1d4e-5f60-4a71-8c92-d3e4f5061728', 'Dan', 'Watts', '2026-05-29 09:24:50+00', '2026-05-29 09:24:50+00');
INSERT INTO project_decision (project_decision_id, project_id, title, context, decision, consequences, author_ern, author_given_name, author_family_name, created_at, updated_at) VALUES ('c16ebc2b-8dac-4654-90c9-306f944a54b4', 'd0cf7a10-0000-4d0c-8a00-000000000001', 'NHSmail-origin tasks are non-authoritative', 'Tasks and match context arriving from NHSmail cannot be treated as a source of truth for patient or clinical routing.', 'NHSmail-origin task and match context is surfaced as advisory only and must be re-verified before any clinical action.', 'Prevents over-trust of unverified inbound context. Requires UX treatment to clearly mark non-authoritative context in the queue and document detail screens.', 'ern:emis:user:user:7ae7b859-c480-4644-b3be-d77d628f6e7e', 'Luke', 'Smith', '2026-05-29 09:31:30+00', '2026-05-29 09:31:30+00');
